krpano.action:
if(!webvr.isenabled AND device.mouse,
	set(global.layer[hs_preview_img].url, get(thumburl));
	calc(global.layer[hs_preview_caption].html, ttitle + ' [span style="color:#38BDF8;"](' + distlbl + ' / ' + dzlbl + ')[/span]');
	set(global.layer[hs_preview_card].visible, true);
	tween(global.layer[hs_preview_card].alpha, 1.0, 0.15);
	asyncloop(hotspot[get(hsname)].hovering,
		copy(global.layer[hs_preview_card].x, mouse.stagex);
		copy(global.layer[hs_preview_card].y, mouse.stagey);
	);
);

hs_hide_thumb_preview();
if(isvalue(caller.linkedscene),
	copy(target_sc, caller.linkedscene);
	copy(target_h, caller.target_hlookat);
	copy(target_v, caller.target_vlookat);
	copy(target_f, caller.target_fov);
	caller.getcenter(ch, cv);
	calc(move_depth, min(max(caller.dist_m * 10, 180), 750));
	set3dtransition("sphere", get(ch), 0, get(move_depth), 0.45, 0, 0.0, 0.65, "easeOutQuad");
	skin_loadscene(get(target_sc), BLEND(0.65, easeOutQuad));
	if(target_h !== null, skin_lookat(get(target_h), get(target_v), get(target_f)); );
);
